            ['kod' => 'MAK-120', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Tüp sabitleme', 'tehlike' => 'Tüpün devrilmesi', 'risk' => 'Vana kırılması ve ağır yaralanma', 'mevcut_onlem' => 'Tüpü uygun sabitleme düzeneğiyle dik ve kararlı tutun. Vana/regülatörü darbeden koruyun; geçiş alanında serbest bırakmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-121', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Zemindeki tüp', 'tehlike' => 'Tüp ve hortumun geçişte kalması', 'risk' => 'Takılma ve bağlantı hasarı', 'mevcut_onlem' => 'Tüpü çalışmaya uygun korunaklı konuma alın. Hortumu geçişten uzak düzenleyin; kullanım dışı ekipmanın vanasını kapatıp güvenli depolayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-122', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Hortum durumu', 'tehlike' => 'Çatlak veya gazla uyumsuz hortum', 'risk' => 'Kaçak ve yangın', 'mevcut_onlem' => 'Gaz türüne uygun hortum, bağlantı ve basınç düzenleme elemanı kullanın. Hasar/yaşlanmayı kontrol edin; geçici tel veya bantla bağlantı yapmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-123', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Kaçak kontrolü', 'tehlike' => 'Kaçağın alevle aranması', 'risk' => 'Alevlenme ve yanık', 'mevcut_onlem' => 'Kaçak kontrolünü uygun köpük veya gaz dedektörüyle yapın. Kaçakta vanayı güvenle kapatın, alanı havalandırın ve tutuşturucu kaynakları kontrol edin; arızalı tüpü kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'MAK-124', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Şaloma bağlantısı', 'tehlike' => 'Alev geri tepmesi riski olan düzende uygunsuz bağlantı', 'risk' => 'Yangın ve patlama', 'mevcut_onlem' => 'Gaz ve şaloma sistemine göre geri tepme/çekvalf gereğini üreticiyle belirleyin. Uygun elemanları doğru yönde takın; ateşleme-kapatma sırasını uygulamalı öğretin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-125', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Regülatör', 'tehlike' => 'Uyumsuz veya hasarlı basınç düşürücü', 'risk' => 'Gaz kaçağı ve yüksek basınç', 'mevcut_onlem' => 'Regülatörü gaz cinsi ve tüp basıncına uygun seçin. Hasarlı göstergeyi değiştirin; bağlantıyı uygun anahtarla yapın ve tedarikçi dışı vana tamirini önleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-126', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Oksijen varsa', 'tehlike' => 'Yağlı el/ekipmanla oksijen donanımına temas', 'risk' => 'Hızlı yanma ve patlama', 'mevcut_onlem' => 'Oksijen varlığını doğrulayın. Oksijen bağlantılarında yağ/grese izin vermeyin; yalnız uyumlu temiz donanım kullanın ve kontaminasyon halinde tedarikçiye başvurun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'MAK-127', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Tüp taşıma', 'tehlike' => 'Tüpün sürüklenmesi veya vanadan kaldırılması', 'risk' => 'Düşme ve vana kırılması', 'mevcut_onlem' => 'Uygun tüp arabası kullanın. Taşımada üreticiye uygun vana korumasını takın; regülatörle taşımayı ve tüpü yuvarlayarak ilerletmeyi önleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'MAK-128', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Kapalı ortam kullanımı', 'tehlike' => 'Kaçağın veya yanma gazının birikmesi', 'risk' => 'Boğulma/zehirlenme', 'mevcut_onlem' => 'Gazın özelliğine uygun havalandırmayı sağlayın. Alçak noktalar ve kapalı hacimleri değerlendirin; gerekli algılama sistemini tasarlayın ve kaçağı teknik kontrolle giderin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-129', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Sıcak çalışma', 'tehlike' => 'Yanıcı malzeme yakınında açık alev', 'risk' => 'Yangın ve ağır yanık', 'mevcut_onlem' => 'Yanıcıları uzaklaştırın ve sıcak çalışma alanını ayırın. Gerekli söndürme donanımını hazır tutun; iş bitiminde kor/ısınma kontrolü ve belirlenen gözetimi uygulayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-130', 'bolum' => 'Gaz tüpleri ve şaloma', 'faaliyet' => 'Kullanım dışı tüpler', 'tehlike' => 'Boş/dolu tüplerin uygunsuz birlikte depolanması', 'risk' => 'Kaçak ve yanlış tüp kullanımı', 'mevcut_onlem' => 'Gaz uyumluluğuna göre depolama yapın, boş/dolu ayrımını işaretleyin. Vanaları kapalı tutun; ısı kaynaklarından uzak, havalandırılan ve kontrollü alan kullanın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); Gaz tedarikçisi talimatı; K10', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
        ]],
        'atolye_elektrik_ve_ortak_makine_guvenligi' => ['Atölye – Elektrik ve ortak makine güvenliği', [
            ['kod' => 'MAK-131', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Açık pano', 'tehlike' => 'Pano iç donanımına yetkisiz erişim', 'risk' => 'Elektrik çarpması ve ölüm', 'mevcut_onlem' => 'Alanı hemen kontrol altına alın. Yetkili elektrik personeli enerji kesme ve gerilimsizlik doğrulaması sonrası iç korumaları tamamlasın; pano kapısını kapalı ve kilitli tutun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-132', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Pano müdahale alanı', 'tehlike' => 'Pano önünde malzeme ve kablo bulunması', 'risk' => 'Takılma, müdahalede gecikme', 'mevcut_onlem' => 'Pano önünü ve güvenli kaçış yolunu boşaltın. Kablo güzergâhını düzenleyin; pano çevresini depolama alanından ayırıp erişimi sürekli açık tutun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-133', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Kablo çıkışı', 'tehlike' => 'Korumasız pano kablo girişleri', 'risk' => 'Yalıtım kesilmesi ve kaçak', 'mevcut_onlem' => 'Kablo girişlerine uygun rakor, kenar koruması ve çekme emniyeti sağlayın. Kabloyu mekanik zorlanmadan ayırın; muhafaza koruma seviyesini koruyun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-134', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Koruma iletkeni', 'tehlike' => 'Topraklama sürekliliğinin kaybı', 'risk' => 'Gövdeye temasta ölüm', 'mevcut_onlem' => 'Makine gövdesi ve ilgili metal parçaların koruma bağlantılarını yetkili kişiye ölçtürün. Gevşek/korozyonlu bağlantıları onarın; ölçüm sonrası uygunluk kaydını saklayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-135', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Devre koruması', 'tehlike' => 'Kablo kesitine/yüke uymayan koruma', 'risk' => 'Aşırı ısınma ve yangın', 'mevcut_onlem' => 'Devre yükü, kablo kesiti ve kesici seçimini hesapla doğrulayın. Kaçak akım korumasının tip ve seçiciliğini tesisata göre belirleyin; atmayı önlemek için korumayı iptal etmeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-136', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Uzatma kabloları', 'tehlike' => 'Zeminde ezilen bağlantılar', 'risk' => 'Elektrik çarpması ve yangın', 'mevcut_onlem' => 'Kalıcı beslemeyi uygun tesisatla sağlayın. Geçici kullanımda mekanik koruma ve uygun kapasite kullanın; geçişlerde korumasız kablo bırakmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-137', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Elektrik bakım işi', 'tehlike' => 'Enerjili çalışma veya yanlış devreyi kesme', 'risk' => 'Ark yanığı ve ölüm', 'mevcut_onlem' => 'Öncelikle enerjisiz çalışmayı planlayın. Devreyi tanımlayıp kilitleyin, uygun ölçü cihazıyla gerilimsizliği doğrulayın; işi yalnız yetkili elektrik personeli yapsın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'MAK-138', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'İzolasyon paspası', 'tehlike' => 'Uygunluğu bilinmeyen paspası koruma sayma', 'risk' => 'Elektrik çarpması', 'mevcut_onlem' => 'Paspasın gerilim sınıfı, işareti ve fiziksel durumunu doğrulayın. Gerekiyorsa uygun yalıtkan ekipmanla değiştirin; paspası enerji izolasyonunun yerine kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'MAK-139', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Enerji geri gelmesi', 'tehlike' => 'Kesinti sonrası kendiliğinden çalışma', 'risk' => 'Kapılma ve ezilme', 'mevcut_onlem' => 'Enerji dönüşünde manuel yeniden başlatma gerektiren güvenli kumanda düzenini doğrulayın. Testi alan boşken yapın; uygunsuz otomatik başlatmayı giderin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'MAK-140', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Emniyet iptali', 'tehlike' => 'Switch veya güvenlik devresinin köprülenmesi', 'risk' => 'Koruma açıkken tehlikeli hareket', 'mevcut_onlem' => 'İptalleri teknik incelemeyle tespit edip kaldırın. Emniyet fonksiyonunu yeniden doğrulayın; üretim baskısı nedeniyle koruma iptalini kabul etmeyen arıza bildirim yöntemi kurun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-141', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Çoklu enerji', 'tehlike' => 'Elektrik dışında pnömatik/ısı enerjisinin unutulması', 'risk' => 'Ani hareket ve yanık', 'mevcut_onlem' => 'Her makinenin enerji haritasını çıkarın. Basınç, ısı, yerçekimi ve atalet enerjilerini güvenli giderin; kişisel kilit ve sıfır enerji denemesini uygulayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'MAK-142', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Ortak bakım', 'tehlike' => 'Bir çalışanın kilidi kaldırıp diğerini içeride bırakması', 'risk' => 'Beklenmeyen hareket ve ölüm', 'mevcut_onlem' => 'Grup kilitleme ve vardiya devir prosedürü uygulayın. Her çalışan kendi kilidini kullansın; alan kontrolü ve tüm kişilerin güvenli çıkışı doğrulanmadan enerji vermeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
            ['kod' => 'MAK-143', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Kontrol/bakım kapsamı', 'tehlike' => 'Güvenlik işlevlerinin plansız kontrolü', 'risk' => 'Gizli arızayla ağır kaza', 'mevcut_onlem' => 'Üretici bakımını, kullanıcı kontrolünü ve mevzuattaki periyodik kontrol kapsamını ayrı planlayın. Ek-III kapsamını ekipman bazında doğrulayın; her makine için gelişigüzel aynı kontrol süresi yazmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-144', 'bolum' => 'Elektrik ve ortak makine güvenliği', 'faaliyet' => 'Makine değişikliği', 'tehlike' => 'İmalat/yenileme sonrası risklerin değerlendirilmemesi', 'risk' => 'Beklenmeyen hareket ve ağır yaralanma', 'mevcut_onlem' => 'Koruyucu, sürücü ve kumanda değişikliklerini teknik dosyada kaydedin. Güvenlik fonksiyonlarını yetkin kişiye doğrulatın; kullanım talimatını ve risk değerlendirmesini güncelleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
        ]],
        'atolye_depolama_ve_calisma_alani' => ['Atölye – Depolama ve çalışma alanı', [
            ['kod' => 'MAK-145', 'bolum' => 'Depolama ve çalışma alanı', 'faaliyet' => 'Metal parça rafı', 'tehlike' => 'Parçaların üst üste ve kenarda bulunması', 'risk' => 'Düşme, ayak/el ezilmesi', 'mevcut_onlem' => 'Parçaları bölmeli ve kenar tutuculu düzenle depolayın. Ağırları alt seviyeye alın; gelişigüzel yüksek istifi azaltın ve güvenli alma sırasını belirleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-146', 'bolum' => 'Depolama ve çalışma alanı', 'faaliyet' => 'Raf kapasitesi', 'tehlike' => 'Taşıma kapasitesinin bilinmemesi', 'risk' => 'Raf çökmesi ve ağır ezilme', 'mevcut_onlem' => 'Rafı yetkin teknik kişiye değerlendirtin. İzin verilen yükleri görünür belirtin; aşırı yükü kaldırın ve hasarlı rafı kullanımdan çıkarın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
